<template><view class="page"><view class="notice">演示数据，请勿录入真实顾客信息</view><view class="top"><text class="title">我的顾客</text><text class="muted">仅展示本人负责的顾客</text></view><input v-model="keyword" class="search card" placeholder="搜索姓名或手机号" /><view class="list"><view v-for="customer in shown" :key="customer.id" class="customer card" @tap="open(customer)"><view class="avatar">{{ customer.name.slice(0,1) }}</view><view class="info"><text class="name">{{ customer.name }} <small>{{ mask(customer.phone) }}</small></text><text>{{ customer.memberLevel }} · {{ customer.store }}</text><text>{{ customer.preferences || '暂无服务偏好' }}</text></view><text class="arrow">›</text></view></view><view v-if="!shown.length" class="empty card">暂无符合条件的顾客</view></view></template>
<script setup>
import { computed, ref } from 'vue'; import { onShow } from '@dcloudio/uni-app'; import { accessibleCustomers, getSession } from '../../services/repository'
const keyword=ref(''), customers=ref([]); const shown=computed(()=>customers.value.filter(c=>`${c.name}${c.phone}`.includes(keyword.value))); function mask(v){return v.replace(/^(\d{3})\d{4}(\d{4})$/, '$1****$2')} function open(c){uni.navigateTo({url:`/pages/customer-detail/index?id=${c.id}`})}; onShow(()=>{const employee=getSession();if(!employee)return uni.reLaunch({url:'/pages/login/index'});customers.value=accessibleCustomers(employee)})
</script>
<style scoped>.top{margin:14rpx 4rpx 24rpx}.title{display:block;font-size:38rpx;font-weight:700}.muted{display:block;margin-top:10rpx}.search{box-sizing:border-box;width:100%;padding:19rpx;font-size:26rpx}.list{margin-top:18rpx}.customer{display:flex;align-items:center;margin-bottom:16rpx;padding:22rpx}.avatar{width:70rpx;height:70rpx;line-height:70rpx;border-radius:50%;background:#e9f1ff;color:#2167e8;text-align:center;font-weight:700}.info{flex:1;margin-left:18rpx}.info text{display:block;margin-top:7rpx;color:#7b8494;font-size:23rpx}.info .name{margin:0;color:#182033;font-size:29rpx;font-weight:700}.name small{margin-left:10rpx;color:#7b8494;font-size:22rpx;font-weight:400}.arrow{font-size:45rpx;color:#b0b8c5}.empty{margin-top:30rpx;padding:70rpx;text-align:center;color:#7b8494}</style>
